  "gabarito": "B",
  "comentario": "**Gabarito: B.** Os processos técnicos cobrem o trabalho de engenharia: análise de negócio ou missão, definição de requisitos das partes interessadas e do sistema, arquitetura, projeto, implementação, integração, verificação, transição, validação, operação, manutenção e desativação. Gestão de riscos e gestão de configuração são processos de **gestão técnica**; gestão de portfólio é **organizacional habilitador de projeto**; aquisição é processo de **acordo**.\n\nRevisar: Apostila 06, §6.",
