  "enunciado": "Uma equipe aumenta progressivamente o número de usuários virtuais de um sistema para **além da capacidade especificada**, até que ele falhe, a fim de identificar o ponto de ruptura e observar como o sistema se recupera. Esse teste é classificado como teste de",
