  "enunciado": "Considere o código PHP a seguir.\n\n```php\n<?php\nclass A {\n    public function quem() { return \"A\"; }\n    public function fala() { return $this->quem(); }\n}\nclass B extends A {\n    public function quem() { return \"B\"; }\n}\n$o = new B();\necho $o->fala();\necho (1 === \"1\") ? \"S\" : \"N\";\necho (1 == \"1\") ? \"S\" : \"N\";\n```\n\nA saída exibida é",
