  "enunciado": "Considere o programa em C a seguir.\n\n```c\n#include <stdio.h>\nint main(void) {\n    int a = 7, b = 2;\n    double x = a / b;\n    int c = a++ + b;\n    printf(\"%.1f %d %d\", x, c, a);\n    return 0;\n}\n```\n\nA saída exibida é",
