  "enunciado": "Considere o código Python a seguir.\n\n```python\ndef f(x):\n    try:\n        return 10 // x\n    except ZeroDivisionError:\n        return -1\n    finally:\n        print(\"fim\", end=\" \")\n\nprint(f(0), f(5))\n```\n\nA saída exibida é",
  "imagem": null,
  "alternativas": {
    "A": "`fim -1 2`",
    "B": "`-1 2 fim fim`",
    "C": "`fim -1 fim 2`",
    "D": "`fim fim -1 2`",
    "E": "`fim fim 0 2`"
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** Os argumentos de `print` são avaliados antes da impressão. Em cada chamada de `f`, o bloco `finally` executa **mesmo havendo `return`**, imprimindo \"fim \". Em `f(0)` ocorre `ZeroDivisionError` e o retorno é -1; em `f(5)`, 10 // 5 = 2. Só então a linha final imprime \"-1 2\".\n\nRevisar: Apostila 05, §22.",
  "tags": [
    "reforco"
  ],
  "embaralhavel": true,
  "status": "validada",
