  "gabarito": "C",
  "comentario": "**Gabarito: C.** `PreparedStatement` pré-compila o comando e trata os parâmetros como **dados**, não como código SQL. `Statement` com concatenação é vulnerável. `ResultSet` representa o resultado; `DriverManager` obtém conexões; `DatabaseMetaData` descreve o banco.\n\nRevisar: Apostila 05, §12.",
