  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Em um bloco PL/SQL, um comando `SELECT ... INTO` que encontra **três linhas** provoca a exceção predefinida",
  "imagem": null,
  "alternativas": {
    "A": "`DUP_VAL_ON_INDEX`",
    "B": "`TOO_MANY_ROWS`",
    "C": "`ZERO_DIVIDE`",
    "D": "`CURSOR_ALREADY_OPEN`",
    "E": "`NO_DATA_FOUND`"
  },
  "gabarito": "B",
  "comentario": "**Gabarito: B.** `SELECT ... INTO` deve retornar **exatamente uma linha**. Nenhuma linha gera `NO_DATA_FOUND`; mais de uma gera `TOO_MANY_ROWS`. `DUP_VAL_ON_INDEX` ocorre ao violar índice único.\n\nRevisar: Apostila 05, §27.",
