  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Em um gatilho (*trigger*) Oracle de nível de linha, `BEFORE UPDATE`, os pseudorregistros `:OLD` e `:NEW` contêm, respectivamente,",
  "imagem": null,
  "alternativas": {
    "A": "o nome da tabela e o nome do usuário que executou o comando.",
    "B": "os valores que a linha terá depois da atualização e os valores anteriores a ela.",
    "C": "valores nulos e os valores que a linha terá depois da atualização.",
    "D": "os valores da linha antes da atualização e os valores que ela terá depois da atualização.",
    "E": "os valores da linha antes da atualização e valores nulos."
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** Em `UPDATE`, `:OLD` guarda os valores anteriores e `:NEW` os novos; em gatilho `BEFORE`, `:NEW` pode até ser modificado. Em `INSERT`, `:OLD` é nulo; em `DELETE`, `:NEW` é nulo. Em PL/pgSQL os registros equivalentes são `OLD` e `NEW`, sem os dois-pontos.\n\nRevisar: Apostila 05, §27.",
  "tags": [
    "reforco"
  ],
  "embaralhavel": true,
