  "enunciado": "A tabela `mov(agencia, dia, valor)` contém (A, 1, 10), (A, 2, 20), (B, 1, 5), (A, 3, 30) e (B, 2, 15). Considere a consulta:\n\n```sql\nSELECT agencia, dia,\n       SUM(valor) OVER (PARTITION BY agencia ORDER BY dia) AS acum\nFROM mov;\n```\n\nOs valores de `acum` nas linhas (A, 3) e (B, 2) são, respectivamente,",
