  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "A tabela `fat(mes, valor)` contém (1, 100), (2, 130) e (3, 120). Considere a consulta:\n\n```sql\nSELECT mes, valor - LAG(valor) OVER (ORDER BY mes) AS dif\nFROM fat\nORDER BY mes;\n```\n\nOs valores de `dif` para os meses 1, 2 e 3 são, respectivamente,",
