  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Em SQL, a diferença entre usar `SUM(valor)` com `GROUP BY agencia` e `SUM(valor) OVER (PARTITION BY agencia)` é que",
  "imagem": null,
  "alternativas": {
    "A": "com `GROUP BY` todas as linhas originais são mantidas, e com a função de janela o resultado tem uma linha por agência.",
    "B": "a função de janela exige a cláusula `HAVING` para definir a partição.",
    "C": "as duas formas produzem sempre o mesmo número de linhas.",
    "D": "a função de janela é avaliada antes da cláusula `WHERE`.",
    "E": "com `GROUP BY` o resultado tem uma linha por agência, e com a função de janela todas as linhas originais são mantidas, cada uma com o total de sua agência."
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** `GROUP BY` **colapsa** as linhas de cada grupo em uma só. A função de janela calcula sobre a partição, mas **preserva** cada linha. Funções de janela são avaliadas depois de `WHERE`, `GROUP BY` e `HAVING`; por isso não podem aparecer no `WHERE`.\n\nRevisar: Apostila 05, §7.",
  "tags": [
    "reforco"
  ],
