  "gabarito": "B",
  "comentario": "**Gabarito: B.** O **data lake** guarda dados brutos de qualquer formato, e o esquema é aplicado na leitura. O **data warehouse** guarda dados integrados, tratados e modelados para análise. O **data mart** é um recorte do DW por área ou assunto.\n\nRevisar: Apostila 05, §13.",
