  "gabarito": "D",
  "comentario": "**Gabarito: D.** No **data warehouse**, os dados são transformados e ajustados ao esquema **antes da carga** (*schema-on-write*, processo ETL). No **data lake**, os dados são carregados como estão e o esquema é aplicado **na consulta** (*schema-on-read*, processo ELT).\n\nRevisar: Apostila 05, §13.",
