  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Em governança de dados, a capacidade de identificar a **origem** de um dado e as **transformações** pelas quais ele passou até chegar a um relatório é denominada",
  "imagem": null,
  "alternativas": {
    "A": "normalização de dados.",
    "B": "mascaramento de dados.",
    "C": "particionamento de dados.",
    "D": "linhagem de dados (*data lineage*).",
    "E": "replicação de dados."
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** A **linhagem** dá rastreabilidade: de onde o dado veio, por quais sistemas e regras passou e onde é usado. Ela apoia auditoria, análise de impacto e correção de problemas de qualidade.\n\nRevisar: Apostila 05, §13.",
