  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Considere o trecho HTML a seguir, que usa o sistema de grade do Bootstrap 5.\n\n```html\n<div class=\"row\">\n  <div class=\"col-12 col-md-6 col-lg-4\">A</div>\n  <div class=\"col-12 col-md-6 col-lg-4\">B</div>\n  <div class=\"col-12 col-md-6 col-lg-4\">C</div>\n</div>\n```\n\nEm uma janela com **800 pixels** de largura, as colunas A, B e C são exibidas",
