  "formato": "multipla_5",
  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Uma API lista milhões de registros que recebem inserções frequentes. Em comparação com a paginação por deslocamento (`offset` e `limit`), a paginação **baseada em cursor**",
  "imagem": null,
  "alternativas": {
    "A": "permite saltar diretamente para qualquer número de página.",
    "B": "exige que o servidor mantenha em memória a posição de cada cliente.",
    "C": "torna desnecessário ordenar os resultados.",
    "D": "retorna sempre o total de registros da coleção.",
    "E": "evita itens repetidos ou pulados quando há inserções durante a navegação e mantém bom desempenho em páginas distantes."
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** O cursor aponta para o último item entregue (por exemplo, uma chave ordenada), e o servidor busca \"os próximos N depois dele\". Isso é estável diante de inserções e não obriga o banco a percorrer as linhas anteriores, como ocorre com `OFFSET` alto. A desvantagem é não permitir salto para uma página arbitrária.\n\nRevisar: Apostila 06, §10.",
  "tags": [
    "reforco"
  ],
  "embaralhavel": true,
  "status": "validada",
