  "comentario": "**Gabarito: C.** *Cloud-native* não é \"estar na nuvem\", e sim **ser construído para a nuvem**: contêineres, microsserviços, malhas de serviço, infraestrutura imutável e APIs declarativas. Mover um monólito sem mudanças é apenas *rehost* (*lift and shift*). O modelo vale para nuvens públicas, privadas e híbridas.\n\nRevisar: Apostila 07, §2.",
  "tags": [
    "reforco"
  ],
  "embaralhavel": true,
  "status": "validada",
