  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Ao configurar novas tentativas automáticas (*retries*) em chamadas entre serviços, é uma boa prática",
  "imagem": null,
  "alternativas": {
    "A": "usar espera exponencial com variação aleatória entre as tentativas e aplicá-las a operações idempotentes.",
    "B": "repetir a chamada imediatamente e sem limite de tentativas, até obter sucesso.",
    "C": "aplicar novas tentativas a qualquer operação, inclusive as que não são idempotentes, sem controle de duplicidade.",
    "D": "usar o mesmo intervalo fixo em todos os clientes, para que as tentativas ocorram ao mesmo tempo.",
    "E": "desativar os tempos limite (*timeouts*), para que cada tentativa aguarde indefinidamente."
  },
  "gabarito": "A",
  "comentario": "**Gabarito: A.** Tentativas imediatas e ilimitadas agravam a sobrecarga de um serviço já degradado. O recomendado é **limitar o número**, usar **espera exponencial** (*exponential backoff*) com ***jitter*** para não sincronizar os clientes e garantir **idempotência**, para que a repetição não duplique efeitos. *Timeouts* continuam necessários.\n\nRevisar: Apostila 06, §11.",
  "tags": [
    "reforco"
  ],
  "embaralhavel": true,
  "status": "validada",
