  "comentario": "**Gabarito: D.** A **camada anticorrupção** (*anti-corruption layer*) isola o novo modelo: adaptadores e tradutores convertem os conceitos do legado para os do novo contexto. No padrão conformista o novo sistema aceita o modelo alheio; o núcleo compartilhado acopla os dois sistemas.\n\nRevisar: Apostila 06, §18.",
