  "comentario": "**Gabarito: B.** No *blue/green*, o ambiente ocioso recebe a nova versão, é testado, e o roteador **alterna** todo o tráfego; a reversão é alternar de volta. O custo é manter infraestrutura duplicada. Substituir instâncias uma a uma é atualização gradual (*rolling update*).\n\nRevisar: Apostila 06, §12.",
