  "comentario": "**Gabarito: B.** O mutex garante **exclusão mútua** e tem dono: quem trava é quem destrava. O semáforo é um contador de sinalização: uma thread pode executar `wait` e outra, `signal`, o que o torna útil também para coordenar a ordem de eventos.\n\nRevisar: Apostila 04, §8.",
