  "texto_base": null,
  "enunciado": "Entre os requisitos de uma solução correta para o problema da região crítica, aquele que impede um processo de esperar **indefinidamente** para entrar em sua região crítica é",
  "imagem": null,
  "alternativas": {
    "A": "a posse e espera.",
    "B": "a exclusão mútua.",
    "C": "o progresso.",
    "D": "a espera limitada.",
    "E": "a preempção."
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** **Exclusão mútua**: só um processo por vez na região crítica. **Progresso**: se ninguém está na região crítica, a escolha do próximo não pode ser adiada indefinidamente. **Espera limitada**: há um limite de vezes em que outros passam à frente de quem pediu para entrar, o que evita *starvation*. Posse e espera é condição de deadlock.\n\nRevisar: Apostila 04, §8.",
  "tags": [
    "reforco"
  ],
  "embaralhavel": true,
  "status": "validada",
