  "enunciado": "Um sistema com **3 quadros** de memória, inicialmente vazios, usa o algoritmo de substituição de páginas **FIFO**. Para a sequência de referências 1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5, o número de faltas de página é",
