  "gabarito": "E",
  "comentario": "**Gabarito: E.** Armazenamento **primário**: memória principal e cache, voláteis. **Secundário**: discos rígidos e SSDs, sempre disponíveis (*on-line*). **Terciário**: mídias removíveis de grande capacidade e baixo custo, como fitas e discos ópticos em bibliotecas robotizadas, com acesso mais lento.\n\nRevisar: Apostila 04, §10.",
