  "gabarito": "E",
  "comentario": "**Gabarito: E.** A rede IP é de **datagramas**: sem conexão, cada pacote é independente e pode chegar fora de ordem. Em **circuitos virtuais** (Frame Relay, ATM, MPLS), a rota é definida antes, e os pacotes carregam um identificador curto do circuito e seguem em ordem.\n\nRevisar: Apostila 04, §14.",
