  "comentario": "**Gabarito: A.** A marcação 802.1Q acrescenta 4 bytes ao quadro: o identificador de protocolo e o campo de controle, com **3 bits de prioridade** (802.1p), 1 bit indicador e **12 bits de identificador de VLAN**. Os 6 bits correspondem ao campo DSCP, do cabeçalho IP.\n\nRevisar: Apostila 04, §14.",
