  "comentario": "**Gabarito: C.** **802.11n** (Wi-Fi 4): 2,4 e 5 GHz, introduziu o MIMO. **802.11ac** (Wi-Fi 5): apenas 5 GHz, canais mais largos e MU-MIMO de descida. **802.11ax** (Wi-Fi 6): 2,4 e 5 GHz, **OFDMA** e MU-MIMO nos dois sentidos, com melhor desempenho em ambientes densos.\n\nRevisar: Apostila 04, §14.",
