  "gabarito": "B",
  "comentario": "**Gabarito: B.** Serviços de administração não devem ficar expostos à internet. O acesso deve passar por VPN ou ZTNA, com **MFA**, **menor privilégio**, contas individuais e **auditoria**; o *bastion host* é o ponto único e monitorado de entrada.\n\nRevisar: Apostila 04, §16.",
