  "comentario": "**Gabarito: D.** A **RFC 2544** define testes de avaliação de desempenho (*benchmarking*) para equipamentos de interconexão: vazão, latência, taxa de perda de quadros e rajadas (*back-to-back*). A **RFC 2889** estende a metodologia para **comutadores de rede local**.\n\nRevisar: Apostila 04, §23.",
