  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "Em uma chamada de voz sobre IP, a **variação do atraso** entre a chegada de pacotes consecutivos é denominada",
  "imagem": null,
  "alternativas": {
    "A": "vazão.",
    "B": "*jitter*.",
    "C": "perda de pacotes.",
    "D": "eco.",
    "E": "latência."
  },
  "gabarito": "B",
  "comentario": "**Gabarito: B.** **Latência**: atraso de ponta a ponta. ***Jitter***: variação desse atraso, compensada por um *buffer* no receptor. **Perda de pacotes**: pacotes que não chegam. Voz e vídeo são sensíveis aos três, e por isso recebem prioridade nas políticas de QoS.\n\nRevisar: Apostila 04, §24.",
  "tags": [
    "reforco"
  ],
