  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Um serviço apresenta tempo médio entre falhas (MTBF) de **990 horas** e tempo médio de reparo (MTTR) de **10 horas**. A disponibilidade do serviço é de",
  "imagem": null,
  "alternativas": {
    "A": "99%.",
    "B": "90%.",
    "C": "98%.",
    "D": "99,9%.",
    "E": "99,5%."
  },
  "gabarito": "A",
  "comentario": "**Gabarito: A.** Disponibilidade = MTBF ÷ (MTBF + MTTR) = 990 ÷ (990 + 10) = 990 ÷ 1.000 = 0,99 = 99%.\n\nRevisar: Apostila 04, §22.",
