  "gabarito": "B",
  "comentario": "**Gabarito: B.** É o texto do **art. 23** da LGPD. O Poder Público deve ainda informar, em veículo de fácil acesso, as hipóteses em que trata dados, e **indicar um encarregado**. O consentimento é apenas uma das bases legais e não é a regra no setor público. Segurança pública e defesa nacional estão, ao contrário, fora do alcance da lei (art. 4º).\n\nRevisar: Apostila 04, §20.",
