  "texto_base": null,
  "enunciado": "Em controle de custos de nuvem, a prática de ***rightsizing*** consiste em",
  "imagem": null,
  "alternativas": {
    "A": "desligar os ambientes de produção fora do horário comercial.",
    "B": "trocar de provedor de nuvem a cada ciclo de faturamento.",
    "C": "ajustar o tipo e o tamanho dos recursos ao consumo realmente observado, eliminando capacidade ociosa.",
    "D": "migrar todos os recursos para a região mais barata, independentemente da latência.",
    "E": "contratar sempre o maior tamanho de instância, para evitar gargalos."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** *Rightsizing* compara o que foi **provisionado** com o que é **usado** (CPU, memória, armazenamento) e redimensiona os recursos. É uma das ações típicas de otimização em FinOps, ao lado de desligar recursos ociosos e de usar reservas.\n\nRevisar: Apostila 07, §2.",
  "tags": [
    "reforco"
  ],
