  "texto_base": null,
  "enunciado": "Em computação em nuvem, a **escalabilidade horizontal** consiste em",
  "imagem": null,
  "alternativas": {
    "A": "aumentar a CPU e a memória de uma única instância.",
    "B": "mover a aplicação para outra região.",
    "C": "reduzir o número de zonas de disponibilidade usadas.",
    "D": "trocar o sistema operacional das instâncias.",
    "E": "acrescentar ou remover instâncias que dividem a carga entre si."
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** **Horizontal** (*scale out* e *scale in*): mais ou menos instâncias, em geral atrás de um balanceador de carga; exige que a aplicação não guarde estado local. **Vertical** (*scale up* e *scale down*): mais ou menos recursos na mesma instância. **Elasticidade** é fazer esse ajuste de forma automática, conforme a demanda.\n\nRevisar: Apostila 07, §2.",
  "tags": [
    "reforco"
  ],
  "embaralhavel": true,
