  "enunciado": "No planejamento de continuidade de um serviço em nuvem, os indicadores **RPO** e **RTO** representam, respectivamente,",
  "imagem": null,
  "alternativas": {
    "A": "o tempo médio entre falhas e o tempo médio de reparo.",
    "B": "a perda máxima de dados tolerada, medida em tempo, e o tempo máximo tolerado para restabelecer o serviço.",
    "C": "o percentual de disponibilidade contratado e a multa por descumprimento.",
    "D": "o custo da indisponibilidade por hora e o orçamento de recuperação.",
    "E": "o tempo máximo tolerado para restabelecer o serviço e a perda máxima de dados tolerada, medida em tempo."
  },
  "gabarito": "B",
  "comentario": "**Gabarito: B.** **RPO** (*Recovery Point Objective*): até que ponto no passado os dados podem ser recuperados; define a frequência de cópias de segurança e de replicação. **RTO** (*Recovery Time Objective*): em quanto tempo o serviço deve voltar. Tempo médio entre falhas e de reparo são MTBF e MTTR.\n\nRevisar: Apostila 07, §2.",
